        [TestCaseSource(nameof(NativeCases))]
        public void MatchesOriginalEveryCall(string variant, BattleMovementKind kind, BattleMovementPoint from,
            BattleMovementPoint to, int? flyUp, int? flyDown, int? over, float targetBlend, int deadAt, string expected)
        {
            var plan = new BattleMovementPlan(kind, from, to, flyUp, flyDown, over, targetBlend);
            var movement = new BattleMovement(variant, plan);
            string[] calls = expected.Split('|');
            for (int call = 0; call < calls.Length; call++)
            {
                movement.Step(call != deadAt);
                string[] values = calls[call].Split(',');
                Assert.That(movement.Position.X, Is.EqualTo(Parse(values[0])).Within(0.0002f), $"call {call}, X");
                Assert.That(movement.Position.Y, Is.EqualTo(Parse(values[1])).Within(0.0002f), $"call {call}, Y");
                Assert.That(movement.Position.Z, Is.EqualTo(Parse(values[2])).Within(0.0002f), $"call {call}, Z");
                Assert.That(movement.Blend, Is.EqualTo(Parse(values[3])), $"call {call}, blend");
                Assert.That(movement.Finished, Is.EqualTo(values[4] == "1"), $"call {call}, finished");
                Assert.That(movement.ElapsedTicks, Is.EqualTo(call + 1));
            }
            int before = movement.ElapsedTicks;
            if (movement.Finished)
            {
                movement.Step();
                Assert.That(movement.ElapsedTicks, Is.EqualTo(before));
            }
        }

        [Test]
        public void SnapshotDoesNotExposeTheWriter()
        {
            var plan = new BattleMovementPlan(BattleMovementKind.Run, new BattleMovementPoint(0f, 0f, 0f),
                new BattleMovementPoint(0f, 0f, 100f));
            var movement = new BattleMovement("PAL3", plan);
            BattleMovementSnapshot before = movement.Capture();
            movement.Step();
            BattleMovementSnapshot after = movement.Capture();
            Assert.That(before.Position.Z, Is.Zero);
            Assert.That(before.ElapsedTicks, Is.Zero);
            Assert.That(after.Position.Z, Is.EqualTo(7.6f));
            Assert.That(after.ElapsedTicks, Is.EqualTo(1));
            Assert.That(after.Plan, Is.SameAs(plan));
            Assert.That(after.ElapsedSeconds, Is.EqualTo(0.02d));
        }

        [Test]
        public void ArrivalWithoutAnOverMarkerDoesNotFinishFlying()
        {
            var plan = new BattleMovementPlan(BattleMovementKind.Fly, new BattleMovementPoint(0f, 0f, 0f),
                new BattleMovementPoint(0f, 0f, 100f), flyUpTick: 1, flyDownTick: 30);
            var movement = new BattleMovement("PAL3", plan);
            for (int call = 0; call < 120; call++)
                movement.Step();
            Assert.That(movement.Position.Z, Is.EqualTo(100f));
            Assert.That(movement.Finished, Is.False);
            movement.Step(alive: false);
            Assert.That(movement.Finished, Is.True);
        }

        [Test]
        public void StopFreezesWithoutConsumingAnotherCall()
        {
            var plan = new BattleMovementPlan(BattleMovementKind.Run, new BattleMovementPoint(0f, 0f, 0f),
                new BattleMovementPoint(0f, 0f, 100f));
            var movement = new BattleMovement("PAL3", plan);
            movement.Step();
            BattleMovementSnapshot before = movement.Capture();
            movement.Stop();
            movement.Stop();
            movement.Step();
            Assert.That(movement.Finished, Is.True);
            Assert.That(movement.Position.Z, Is.EqualTo(before.Position.Z));
            Assert.That(movement.Blend, Is.EqualTo(before.Blend));
            Assert.That(movement.ElapsedTicks, Is.EqualTo(before.ElapsedTicks));
        }

        private static float Parse(string value) => float.Parse(value, CultureInfo.InvariantCulture);
    }
